class Resources:
    """Every resource family, as attributes of the client."""

    me: MeResource
    billing: BillingResource
    usage: UsageResource
    catalog: CatalogResource
    instances: InstancesResource
    networks: NetworksResource
    public_ips: PublicIpsResource
    load_balancers: LoadBalancersResource
    security_groups: SecurityGroupsResource
    volumes: VolumesResource
    snapshots: SnapshotsResource
    databases: DatabasesResource
    kubernetes: KubernetesResource
    ssh_keys: SshKeysResource
    webhooks: WebhooksResource
    migrate: MigrateResource
    certificates: CertificatesResource
    iam: IamResource
    registry: RegistryResource
    dns: DnsResource
    domains: DomainsResource
    operations: OperationsResource

    def _init_resources(self, client: SyncAPIClient) -> None:
        self.me = MeResource(client)
        self.billing = BillingResource(client)
        self.usage = UsageResource(client)
        self.catalog = CatalogResource(client)
        self.instances = InstancesResource(client)
        self.networks = NetworksResource(client)
        self.public_ips = PublicIpsResource(client)
        self.load_balancers = LoadBalancersResource(client)
        self.security_groups = SecurityGroupsResource(client)
        self.volumes = VolumesResource(client)
        self.snapshots = SnapshotsResource(client)
        self.databases = DatabasesResource(client)
        self.kubernetes = KubernetesResource(client)
        self.ssh_keys = SshKeysResource(client)
        self.webhooks = WebhooksResource(client)
        self.migrate = MigrateResource(client)
        self.certificates = CertificatesResource(client)
        self.iam = IamResource(client)
        self.registry = RegistryResource(client)
        self.dns = DnsResource(client)
        self.domains = DomainsResource(client)
        self.operations = OperationsResource(client)
